#!/usr/bin/env -S deno run -A
import { job, workflow } from "jsr:@david/gagen@^0.5.0";

const buildJob = job("build", {
  name: "check updates",
  if: "github.repository == 'dprint/dprint-plugin-clang-format'",
  runsOn: "ubuntu-latest",
  // a new LLVM version means a full nested LLVM build, possibly several times
  // while the AI fixer iterates
  timeoutMinutes: 240,
  steps: [
    {
      name: "Clone repository",
      uses: "actions/checkout@v6",
      with: { token: "${{ secrets.GH_DPRINTBOT_PAT }}" },
    },
    { uses: "denoland/setup-deno@v2" },
    // the update script runs `mise run test` and `mise run hygiene` as its
    // checks. The mise toolchain also provides node, which the update script
    // needs to install and run the OpenAI Codex CLI (@openai/codex) when it
    // has to reconcile an LLVM update.
    { uses: "./.github/actions/setup-ci-deps" },
    {
      name: "Run script",
      env: {
        OPENAI_API_KEY: "${{ secrets.OPENAI_API_KEY }}",
        // authenticates the GitHub API request for the latest LLVM release
        GITHUB_TOKEN: "${{ github.token }}",
        // The fixer and the reviewer use the default model of the Codex CLI.
        // Set CODEX_MODEL or REVIEW_MODEL here to pin the model of either.
      },
      run: [
        `git config user.email "dprintbot@users.noreply.github.com"`,
        `git config user.name "dprintbot"`,
        "deno run -A ./scripts/update.ts",
      ],
    },
  ],
});

// This is necessary to prevent GH automatically disabling this workflow after 60 days.
const keepaliveJob = job("workflow-keepalive", {
  if: "github.event_name == 'schedule'",
  runsOn: "ubuntu-latest",
  permissions: { actions: "write" },
  steps: [
    {
      uses:
        "liskin/gh-workflow-keepalive@f72ff1a1336129f29bf0166c0fd0ca6cf1bcb38c",
    },
  ],
});

workflow({
  name: "check_updates",
  on: {
    workflow_dispatch: {},
    schedule: [{ cron: "0 7 * * *" }],
  },
  jobs: [buildJob, keepaliveJob],
}).writeOrLint({
  filePath: new URL("./check_updates.generated.yml", import.meta.url),
  header: "# GENERATED BY ./check_updates.ts -- DO NOT DIRECTLY EDIT",
  pinDeps: true,
});
